CREATE OR REPLACE FUNCTION public.squad_daily_accounting(p_team uuid) RETURNS TABLE(user_id uuid,day date,logged_reps bigint,net_bank bigint,rolling_reps bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
WITH l AS (SELECT l.user_id,l.log_date AS day,sum(l.reps)::bigint reps,coalesce(sum(l.reps) FILTER(WHERE l.logged_at>=now()-interval '48 hours' AND l.logged_at<=now()),0)::bigint rolling FROM pushup_logs l JOIN team_members m ON m.user_id=l.user_id AND m.team_id=p_team GROUP BY l.user_id,l.log_date), b AS (SELECT b.user_id,b.entry_date AS day,sum(CASE WHEN b.kind='withdrawal' THEN b.reps ELSE -b.reps END)::bigint net,coalesce(sum(CASE WHEN b.kind='withdrawal' THEN b.reps ELSE -b.reps END) FILTER(WHERE b.created_at>=now()-interval '48 hours' AND b.created_at<=now()),0)::bigint rolling FROM bank_entries b JOIN team_members m ON m.user_id=b.user_id AND m.team_id=p_team GROUP BY b.user_id,b.entry_date)
SELECT coalesce(l.user_id,b.user_id),coalesce(l.day,b.day),coalesce(l.reps,0),coalesce(b.net,0),coalesce(l.rolling,0)+coalesce(b.rolling,0) FROM l FULL JOIN b ON l.user_id=b.user_id AND l.day=b.day;
$$;
REVOKE ALL ON FUNCTION public.squad_daily_accounting(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.squad_daily_accounting(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.transfer_banked_reps(p_reps integer,p_kind text,p_day date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=auth.uid(); entry uuid; balance bigint; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF p_reps<1 OR p_reps>500 OR p_kind NOT IN ('deposit','withdrawal') THEN RAISE EXCEPTION 'Invalid bank transfer'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(u::text,0)); INSERT INTO bank_entries(user_id,reps,kind,entry_date) VALUES(u,p_reps,p_kind,p_day) RETURNING id INTO entry; SELECT coalesce(sum(CASE WHEN kind='deposit' THEN reps ELSE -reps END),0) INTO balance FROM bank_entries WHERE user_id=u; RETURN jsonb_build_object('entryId',entry,'balance',balance); END; $$;
REVOKE ALL ON FUNCTION public.transfer_banked_reps(integer,text,date) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.transfer_banked_reps(integer,text,date) TO authenticated,service_role;